CREATE TABLE `UserConsent` (`id` CHAR(36) NOT NULL, `userId` CHAR(36) NOT NULL, `type` VARCHAR(80) NOT NULL, `version` VARCHAR(40) NOT NULL, `accepted` BOOLEAN NOT NULL, `ipAddress` VARCHAR(64) NULL, `userAgent` VARCHAR(512) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `UserConsent_userId_type_version_key` (`userId`,`type`,`version`), KEY `UserConsent_type_createdAt_idx` (`type`,`createdAt`), CONSTRAINT `UserConsent_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
